#!/usr/bin/env node
import {
  fetchLatestVersion,
  isNewerVersion
} from "./chunk-YSOKJIZY.js";
import "./chunk-XYNQ6JGJ.js";
import "./chunk-MBLQFY4T.js";
import {
  version
} from "./chunk-37DSMZOH.js";
import {
  ExitCode,
  GramCLIError,
  getErrorMessage
} from "./chunk-IXNX2GX7.js";

// src/commands/upgrade.ts
import { defineCommand } from "citty";
import { log, spinner, note, confirm, isCancel, cancel } from "@clack/prompts";
import { spawn } from "child_process";
var INSTALL_ARGS = ["install", "-g", "@gram-lang/cli@latest"];
function runNpmInstall() {
  return new Promise((resolve, reject) => {
    const child = spawn("npm", INSTALL_ARGS, { stdio: "inherit" });
    child.on("error", (err) => {
      if (err.code === "ENOENT")
        reject(new Error('"npm" is not available in PATH'));
      else reject(err);
    });
    child.on("close", (code) => {
      if (code === 0) resolve();
      else
        reject(
          new Error(`npm ${INSTALL_ARGS.join(" ")} exited with code ${code}`)
        );
    });
  });
}
var upgrade_default = defineCommand({
  meta: {
    name: "upgrade",
    version,
    description: "Check for and install the latest gram version"
  },
  async run() {
    const s = spinner();
    s.start("Checking for updates\u2026");
    let latest;
    try {
      latest = await fetchLatestVersion();
    } catch (err) {
      s.stop("Could not check for updates.");
      throw new GramCLIError(
        `Could not check for updates: ${getErrorMessage(err)}`,
        ExitCode.Error
      );
    }
    s.stop(`Latest version: ${latest}`);
    if (!isNewerVersion(latest, version)) {
      log.success(`gram is already up to date (v${version}).`);
      return;
    }
    note(
      `Update available: ${version} \u2192 ${latest}
Run: npm ${INSTALL_ARGS.join(" ")}`,
      "gram update available"
    );
    const proceed = await confirm({
      message: `Install @gram-lang/cli@${latest} now?`,
      initialValue: true
    });
    if (isCancel(proceed) || !proceed) {
      cancel("Upgrade cancelled.");
      return;
    }
    try {
      await runNpmInstall();
    } catch (err) {
      throw new GramCLIError(
        `Failed to install the update: ${getErrorMessage(err)}`,
        ExitCode.Error
      );
    }
    log.success(`Installed gram v${latest}.`);
  }
});
export {
  upgrade_default as default
};
